//! End-to-end tests of the patch-wise transport against the REAL Python image service
//! (real payload-aware cover generation, real segmentation, knowledge-base selection, ten real algorithms,
//! real PNG files). The service is spawned on a free loopback port; every cover is generated by it with
//! OS randomness, exactly as in operation -- no test cover is injected anywhere.
//!
//! If python3/numpy/Pillow/Flask are unavailable these tests FAIL loudly
//! (set IOD_E2E_ALLOW_SKIP=1 to turn that into a visible skip message).

use iod_core::api::state::SimulationState;
use iod_core::transport::backend::{HttpBackend, StegoBackend};
use iod_core::transport::error::StegoError;
use iod_core::transport::config::StegoConfig;
use iod_core::transport::pipeline::{self, MessageRequest};
use serde_json::{json, Value};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

const SECRET: &str = "E2E-SECRET-PLAINTEXT-777";

struct Py {
    child: Child,
    port: u16,
    dir: PathBuf,
}
impl Drop for Py {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf()
}

fn python() -> String {
    std::env::var("IOD_TEST_PYTHON").unwrap_or_else(|_| "python3".into())
}

fn free_port() -> u16 {
    let l = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    l.local_addr().unwrap().port()
}

fn start_python(tag: &str) -> Option<Py> {
    let ok = Command::new(python()).args(["-c", "import numpy, PIL, flask"]).stdout(Stdio::null()).stderr(Stdio::null()).status().map(|s| s.success()).unwrap_or(false);
    if !ok {
        if std::env::var("IOD_E2E_ALLOW_SKIP").ok().as_deref() == Some("1") {
            eprintln!("SKIPPED ({tag}): python3 with numpy, Pillow and Flask is not available");
            return None;
        }
        panic!("python3 with numpy, Pillow and Flask is required for the real end-to-end tests (set IOD_E2E_ALLOW_SKIP=1 to skip visibly)");
    }
    let dir = std::env::temp_dir().join(format!("iod-e2e-{tag}-{}-{}", std::process::id(), rand::random::<u32>()));
    std::fs::create_dir_all(dir.join("artifacts")).unwrap();
    let port = free_port();
    let child = Command::new(python())
        .arg(repo_root().join("python-service/src/app.py"))
        .env("IOD_PYTHON_PORT", port.to_string())
        .env("IOD_STEGO_ARTIFACT_DIR", dir.join("artifacts"))
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("spawn python service");
    let py = Py { child, port, dir };
    let start = Instant::now();
    loop {
        if std::net::TcpStream::connect_timeout(&format!("127.0.0.1:{port}").parse().unwrap(), Duration::from_millis(200)).is_ok() {
            std::thread::sleep(Duration::from_millis(200));
            return Some(py);
        }
        assert!(start.elapsed() < Duration::from_secs(30), "python service did not start");
        std::thread::sleep(Duration::from_millis(150));
    }
}

fn cfg(py: &Py) -> StegoConfig {
    let mut c = StegoConfig::default();
    c.python_url = format!("http://127.0.0.1:{}", py.port);
    c.artifact_dir = py.dir.join("artifacts").to_string_lossy().to_string();
    c.max_frame_bytes = 16 * 1024;
    c.http_timeout_ms = 60_000;
    c
}

fn state(py: &Py) -> (Mutex<SimulationState>, String) {
    state_with(py, 16 * 1024)
}

fn state_with(py: &Py, max_frame: usize) -> (Mutex<SimulationState>, String) {
    let mut c = cfg(py);
    c.max_frame_bytes = max_frame;
    let backend = Arc::new(HttpBackend::new(&c).unwrap());
    let mut s = SimulationState::with_backend(&py.dir.join("s.db").to_string_lossy(), c, backend).unwrap();
    s.create_group("g1").unwrap();
    for d in ["drone-1", "drone-2"] {
        s.create_drone(d).unwrap();
        s.register_drone(d, "g1", "member").unwrap();
    }
    let (sid, rep) = s.authenticate("drone-1", "drone-2").unwrap();
    assert!(rep.authenticated);
    s.establish_group_key(&sid, "mission-e2e").unwrap();
    (Mutex::new(s), sid)
}

fn req(sid: &str, from: &str, text: &str, cover_generation: Value) -> MessageRequest {
    MessageRequest { session_id: sid.into(), from_id: from.into(), plaintext: text.as_bytes().to_vec(), cover_generation, origin: "e2e" }
}

fn cover_pngs(py: &Py) -> usize {
    std::fs::read_dir(py.dir.join("artifacts")).unwrap().filter(|f| f.as_ref().unwrap().file_name().to_string_lossy().ends_with(".cover.png")).count()
}

/// The real HTTP backend with a switch that makes the next N encodes fail the way a patch that
/// cannot be re-extracted does. Everything else (generation, planning, embedding) is the real service.
struct FlakyEncode {
    inner: HttpBackend,
    fail_encodes: Mutex<u32>,
    plans: Mutex<Vec<(Value, Value)>>,
    encodes: Mutex<Vec<String>>,
}
impl StegoBackend for FlakyEncode {
    fn health(&self) -> Result<Value, StegoError> { self.inner.health() }
    fn plan(&self, r: &Value) -> Result<Value, StegoError> {
        let out = self.inner.plan(r)?;
        self.plans.lock().unwrap().push((r.clone(), out.clone()));
        Ok(out)
    }
    fn encode(&self, r: &Value) -> Result<Value, StegoError> {
        self.encodes.lock().unwrap().push(r["cover_id"].as_str().unwrap_or("").to_string());
        let mut n = self.fail_encodes.lock().unwrap();
        if *n > 0 {
            *n -= 1;
            return Err(StegoError::new("PATCH_EMBED_FAILED", "embed", 422, "induced: patch failed immediate re-extraction"));
        }
        drop(n);
        self.inner.encode(r)
    }
    fn extract(&self, id: &str, l: &Value) -> Result<Value, StegoError> { self.inner.extract(id, l) }
    fn kb(&self) -> Result<Value, StegoError> { self.inner.kb() }
    fn learn_get(&self, p: &str) -> Result<Value, StegoError> { self.inner.learn_get(p) }
    fn learn_post(&self, p: &str, b: &Value) -> Result<Value, StegoError> { self.inner.learn_post(p, b) }
}

fn helper(mode: &str, path: &Path, args: &[&str]) -> String {
    let mut c = Command::new(python());
    c.arg("-I").arg(repo_root().join("rust-core/tests/helpers/tamper_png.py")).arg(mode).arg(path).args(args);
    let out = c.output().unwrap();
    assert!(out.status.success(), "helper {mode} failed: {}", String::from_utf8_lossy(&out.stderr));
    String::from_utf8_lossy(&out.stdout).to_string()
}

fn png_path(py: &Py, id: &str) -> PathBuf {
    py.dir.join("artifacts").join(format!("{id}.png"))
}

fn stego_pngs(py: &Py) -> usize {
    std::fs::read_dir(py.dir.join("artifacts")).unwrap().filter(|f| {
        let n = f.as_ref().unwrap().file_name().to_string_lossy().to_string();
        n.ends_with(".png") && n.matches('.').count() == 1
    }).count()
}

fn check_sequential(manifest: &Value, payload: u64) {
    let mut off = 0u64;
    for p in manifest["patches"].as_array().unwrap().iter().filter(|p| p["used"] == true) {
        assert_eq!(p["payload_offset"].as_u64().unwrap(), off);
        assert!(p["payload_length"].as_u64().unwrap() >= 1);
        off += p["payload_length"].as_u64().unwrap();
    }
    assert_eq!(off, payload, "chunks cover the payload exactly once");
}

#[test]
fn both_directions_real_png_patchwise_on_fresh_generated_covers() {
    let Some(py) = start_python("roundtrip") else { return };
    let (st, sid) = state(&py);
    let mut covers = std::collections::BTreeSet::new();
    for (from, text) in [("drone-1", format!("patch-wise d1->d2 {SECRET}")), ("drone-2", format!("patch-wise d2->d1 {SECRET} \u{1F681}"))] {
        let v = pipeline::run_message(&st, req(&sid, from, &text, Value::Null)).unwrap_or_else(|f| panic!("{}", f.error));
        assert_eq!(v["delivered_message"], text);
        // a fresh cover generated locally under the Raspberry Pi 5 resource profile
        assert_eq!(v["cover"]["source"], "generated");
        assert_eq!((v["cover"]["width"].as_u64(), v["cover"]["height"].as_u64(), v["cover"]["mode"].as_str()), (Some(320), Some(240), Some("RGB")));
        assert_eq!(v["cover"]["generator_version"], "procgen-1");
        assert!(["terrain", "clouds", "strata", "cells"].contains(&v["cover"]["family"].as_str().unwrap()));
        assert_eq!(v["cover"]["seed_fingerprint"].as_str().unwrap().len(), 16);
        let g = &v["generation"];
        assert_eq!(g["profile"], "raspberry_pi_5_cpu");
        assert_eq!(g["seeding"], "os-random");
        let n = g["candidate_count"].as_u64().unwrap();
        assert!((1..=2).contains(&n), "at most two candidates under the profile");
        assert_eq!(g["candidates"].as_array().unwrap().iter().filter(|c| c["outcome"] == "selected").count(), 1);
        assert!(g["candidates"].as_array().unwrap().iter().all(|c| c["quality_score"].is_number() && c["rejection_reasons"].is_array()));
        assert!(v["cover"]["quality_score"].as_f64().unwrap() >= 0.70);
        assert_eq!(g["budget"]["limit_ms"], 2500);
        assert!(g["budget"]["used_ms"].as_f64().unwrap() > 0.0);
        for k in ["generate", "prescreen", "plan", "total"] {
            assert!(g["timings_ms"][k].is_number(), "{k}");
        }
        // no raw seed anywhere in the public response or next to the stored cover
        let cid0 = v["cover"]["artifact_id"].as_str().unwrap();
        assert!(!v.to_string().contains("\"seed\"") && !v.to_string().contains("seed_hex"));
        let meta = std::fs::read_to_string(py.dir.join("artifacts").join(format!("{cid0}.gen.json"))).unwrap();
        assert!(!meta.contains("\"seed\"") && meta.contains("seed_fingerprint"));
        covers.insert(cid0.to_string());
        assert_eq!(v["verification"]["frame_match"], true);
        assert_eq!(v["verification"]["resegmented"], false);
        assert_eq!(v["manifest"], v["received_manifest"], "the receiver authenticated exactly the planned manifest");
        assert!(v["stages"].as_array().unwrap().iter().all(|s| s["status"] == "ok"));
        assert_eq!(v["embed"]["exact_frame_recovery_from_saved_png"], true);
        let payload = v["transport"]["payload_section_bytes"].as_u64().unwrap();
        check_sequential(&v["manifest"], payload);
        // the saved artifact is a real PNG whose embedded bootstrap + manifest an INDEPENDENT reader agrees with
        let id = v["artifact"]["id"].as_str().unwrap();
        let bytes = std::fs::read(png_path(&py, id)).unwrap();
        assert_eq!(&bytes[..8], b"\x89PNG\r\n\x1a\n");
        let dump: Value = serde_json::from_str(&helper("dump", &png_path(&py, id), &[])).unwrap();
        assert_eq!(dump["crc_ok"], true);
        assert_eq!(dump["frame_len"], v["transport"]["frame_bytes"]);
        assert_eq!(dump["manifest_len"], v["transport"]["manifest_bytes"]);
        assert_eq!(dump["patch_count"], v["manifest"]["patch_count"]);
        assert_eq!(dump["reserved_rows"], v["manifest"]["reserved_rows"]);
        for (d, m) in dump["patches"].as_array().unwrap().iter().zip(v["manifest"]["patches"].as_array().unwrap()) {
            if m["used"] == true {
                assert_eq!(d["alg_id"], m["alg_id"]);
                assert_eq!(d["param"], m["param"]);
                assert_eq!(d["offset"], m["payload_offset"]);
                assert_eq!(d["length"], m["payload_length"]);
            } else {
                assert_eq!(d["alg_id"], 0);
            }
        }
        // per-patch records: selected algorithm comes from the knowledge-base ranking, with real scores
        for p in v["plan"]["patches"].as_array().unwrap().iter().filter(|p| p["used"] == true) {
            assert_eq!(p["retrieval"]["ranking"][0], p["selected"]);
            assert_eq!(p["retrieval"]["selector_version"], "kb-bm25-1");
            assert!(p["retrieval"]["candidates"].as_array().unwrap().len() == 10);
            assert_eq!(p["dry_run"]["ok"], true);
        }
        for p in v["embed"]["patches"].as_array().unwrap().iter().filter(|p| p["used"] == true) {
            assert_eq!(p["extraction"], "verified_from_saved_png");
        }
        // inspection images exist and are served by id only
        let cfg = st.lock().unwrap().stego_cfg.clone();
        let cid = v["cover"]["artifact_id"].as_str().unwrap();
        for (aid, kind) in [(cid, "cover"), (cid, "seg"), (cid, "labels"), (id, "diff"), (id, "stego")] {
            assert_eq!(&pipeline::artifact_png(&cfg, aid, kind).unwrap()[..4], b"\x89PNG", "{kind}");
        }
    }
    assert_eq!(covers.len(), 2, "each transmission has its own cover");
    assert_eq!(cover_pngs(&py), 2, "exactly one stored cover per transmission");
    let evs = st.lock().unwrap().db.query_stego_events(&Default::default()).unwrap();
    assert_eq!(evs.len(), 2);
    assert!(evs.iter().all(|e| e["success"] == true && e["patches"].as_array().map(|a| !a.is_empty()).unwrap_or(false)));
    assert!(evs.iter().all(|e| e["cover_source"] == "generated" && e["covers_generated"] == 1 && e["seed_fingerprint"].is_string()
        && e["timings_ms"]["cover_generate"].as_f64().unwrap() > 0.0 && e["generation"]["candidates"].is_array()));
    assert!(!serde_json::to_string(&evs).unwrap().contains(SECRET));
    // receive-only: nothing is generated or planned on the receiving side
    let sent = pipeline::run_send(&st, req(&sid, "drone-1", "handoff", Value::Null)).unwrap_or_else(|f| panic!("{}", f.error));
    let n = cover_pngs(&py);
    let r = pipeline::run_receive(&st, &sid, "drone-2", sent["artifact"]["id"].as_str().unwrap()).unwrap_or_else(|f| panic!("{}", f.error));
    assert_eq!(r["delivered_message"], "handoff");
    assert_eq!(cover_pngs(&py), n, "the receiver generated no cover");
}

#[test]
fn generated_covers_are_split_into_irregular_patches_using_several_algorithms() {
    let Some(py) = start_python("mixed") else { return };
    let (st, sid) = state(&py);
    let mut seen = std::collections::BTreeSet::new();
    let mut families = std::collections::BTreeSet::new();
    for (i, n) in [60usize, 400, 1500, 3000, 200, 900, 2500, 120].into_iter().enumerate() {
        let from = if i % 2 == 0 { "drone-1" } else { "drone-2" };
        let text = "m".repeat(n);
        let v = pipeline::run_message(&st, req(&sid, from, &text, Value::Null)).unwrap_or_else(|f| panic!("{n}: {}", f.error));
        assert_eq!(v["delivered_message"].as_str().unwrap().len(), n);
        assert_eq!(v["cover"]["width"], 320);
        assert_eq!(v["cover"]["mode"], "RGB");
        families.insert(v["cover"]["family"].as_str().unwrap().to_string());
        assert!(v["manifest"]["patch_count"].as_u64().unwrap() >= 2);
        check_sequential(&v["manifest"], v["transport"]["payload_section_bytes"].as_u64().unwrap());
        for (a, _) in v["plan"]["algorithms_used"].as_object().unwrap() {
            seen.insert(a.clone());
        }
        // patches partition the image exactly; they are content-shaped, not a fixed grid
        let dump: Value = serde_json::from_str(&helper("dump", &png_path(&py, v["artifact"]["id"].as_str().unwrap()), &[])).unwrap();
        let px: Vec<u64> = dump["pixels_per_patch"].as_array().unwrap().iter().map(|x| x.as_u64().unwrap()).collect();
        assert_eq!(px.iter().sum::<u64>(), 320 * 240, "every pixel in exactly one patch");
        let sizes: std::collections::BTreeSet<u64> = px.iter().copied().collect();
        assert!(sizes.len() >= 2 || px.len() < 2, "{sizes:?}");
    }
    assert!(seen.len() >= 2, "expected different algorithms across patches/covers, got {seen:?}");
    assert!(families.len() >= 2, "several generator families are used across transmissions, got {families:?}");
    // On ONE stored cover the plan is deterministic (this is what a re-plan relies on) and nothing new is generated.
    let backend = st.lock().unwrap().backend.clone();
    let cfg = st.lock().unwrap().stego_cfg.clone();
    let first = backend.plan(&json!({"payload_bytes": 500, "cover_generation": cfg.generator.to_json(), "limits": cfg.limits()})).unwrap();
    let cid = first["cover"]["artifact_id"].as_str().unwrap().to_string();
    let before = cover_pngs(&py);
    let re = |lvl: u32| backend.plan(&json!({"payload_bytes": 500, "replan_cover_id": cid, "limits": cfg.limits(), "min_level": lvl})).unwrap();
    let (a, b) = (re(0), re(0));
    assert_eq!(cover_pngs(&py), before, "a re-plan never generates a cover");
    assert_eq!(a["cover"]["artifact_id"], cid.as_str());
    assert_eq!(a["cover"]["sha256"], first["cover"]["sha256"]);
    assert_eq!(a["manifest_b64"], b["manifest_b64"]);
    assert_eq!(a["manifest_b64"], first["manifest_b64"], "planning the stored cover reproduces the plan made when it was generated");
    assert_eq!(a["generation"]["reused_for_replan"], true);
    let essence = |v: &Value| v["plan"]["patches"].as_array().unwrap().iter()
        .map(|p| (p["selected"].clone(), p["payload_offset"].clone(), p["payload_length"].clone(), p["retrieval"].clone(), p["features"].clone())).collect::<Vec<_>>();
    assert_eq!(essence(&a), essence(&b), "features, retrieval scores and allocation are reproducible");
    // a coarser level never has more patches
    let c = re(2);
    assert!(c["plan"]["patch_count"].as_u64().unwrap() <= a["plan"]["patch_count"].as_u64().unwrap());
    assert_eq!(c["cover"]["artifact_id"], cid.as_str());
}

#[test]
fn an_induced_replan_reuses_the_same_generated_cover_end_to_end() {
    let Some(py) = start_python("replan") else { return };
    let c = cfg(&py);
    let flaky = Arc::new(FlakyEncode { inner: HttpBackend::new(&c).unwrap(), fail_encodes: Mutex::new(1), plans: Mutex::new(vec![]), encodes: Mutex::new(vec![]) });
    let mut s = SimulationState::with_backend(&py.dir.join("s.db").to_string_lossy(), c, flaky.clone() as Arc<dyn StegoBackend>).unwrap();
    s.create_group("g1").unwrap();
    for d in ["drone-1", "drone-2"] {
        s.create_drone(d).unwrap();
        s.register_drone(d, "g1", "member").unwrap();
    }
    let (sid, rep) = s.authenticate("drone-1", "drone-2").unwrap();
    assert!(rep.authenticated);
    s.establish_group_key(&sid, "mission-replan").unwrap();
    let st = Mutex::new(s);
    let text = format!("re-planned {}", "r".repeat(700));
    let v = pipeline::run_message(&st, req(&sid, "drone-1", &text, Value::Null)).unwrap_or_else(|f| panic!("{}", f.error));
    assert_eq!(v["delivered_message"], text);
    let plans = flaky.plans.lock().unwrap().clone();
    let encodes = flaky.encodes.lock().unwrap().clone();
    assert_eq!((plans.len(), encodes.len()), (2, 2), "one failed embed -> exactly one re-plan");
    let cid = plans[0].1["cover"]["artifact_id"].as_str().unwrap().to_string();
    // first plan generated; the re-plan named the stored cover and generated nothing
    assert!(plans[0].0["cover_generation"].is_object() && plans[0].0.get("replan_cover_id").is_none());
    assert_eq!(plans[1].0["replan_cover_id"], cid.as_str());
    assert!(plans[1].0.get("cover_generation").is_none());
    assert_eq!(plans[1].1["cover"]["artifact_id"], cid.as_str());
    assert_eq!(plans[1].1["cover"]["sha256"], plans[0].1["cover"]["sha256"], "same pixels");
    assert_eq!(plans[1].1["generation"]["reused_for_replan"], true);
    assert!(plans[1].1["plan"]["refinement_level"].as_u64().unwrap() > plans[0].1["plan"]["refinement_level"].as_u64().unwrap());
    assert!(encodes.iter().all(|e| e == &cid), "both encodes loaded that exact cover");
    assert_eq!(cover_pngs(&py), 1, "one cover on disk for the whole transmission");
    assert_eq!(v["cover"]["artifact_id"], cid.as_str());
    let ev = &st.lock().unwrap().db.query_stego_events(&Default::default()).unwrap()[0];
    assert_eq!(ev["replans"].as_array().unwrap().len(), 1);
    assert_eq!(ev["covers_generated"], 1);
    assert_eq!(ev["cover_artifact_id"], cid.as_str());
    // the stego image really is that cover plus the embedding: same geometry, measured distortion is small
    assert_eq!(v["artifact"]["width"], v["cover"]["width"]);
    assert!(v["embed"]["metrics"]["psnr"].as_f64().unwrap() > 30.0);
}

#[test]
fn pixel_level_tampering_of_real_pngs_fails_closed() {
    let Some(py) = start_python("tamper") else { return };
    let (st, sid) = state(&py);
    // (helper mode, args, acceptable stable codes). `U` = the first used patch id, `N` = an unused/other id.
    let cases: &[(&str, &[&str], &[&str])] = &[
        // --- payload area: Python cannot notice; the Rust MAC must (or extraction itself fails closed)
        ("flip-patch", &["U"], &["FRAME_AUTH_FAILED", "EXTRACT_FAILED"]),
        ("flip-patch", &["U", "40", "COVER"], &["FRAME_AUTH_FAILED", "EXTRACT_FAILED"]),
        // --- manifest fields rewritten WITH a valid carrier CRC (CRC is not authentication)
        ("manifest-entry", &["U", "alg", "SWAP"], &["FRAME_AUTH_FAILED", "EXTRACT_FAILED", "MANIFEST_INVALID"]),
        ("manifest-entry", &["U", "alg", "11"], &["UNKNOWN_ALGORITHM"]),
        ("manifest-entry", &["U", "alg", "200"], &["UNKNOWN_ALGORITHM"]),
        ("manifest-entry", &["U", "param", "33"], &["FRAME_AUTH_FAILED", "EXTRACT_FAILED", "MANIFEST_INVALID"]),
        ("manifest-entry", &["U", "offset", "7"], &["MANIFEST_INVALID"]),
        ("manifest-entry", &["U", "length", "1"], &["MANIFEST_INVALID"]),
        ("manifest-entry", &["U", "length", "4000000000"], &["MANIFEST_INVALID"]),
        ("manifest-move-byte", &[], &["FRAME_AUTH_FAILED", "EXTRACT_FAILED"]),
        ("manifest-relabel", &["U", "OTHER"], &["FRAME_AUTH_FAILED", "EXTRACT_FAILED", "MANIFEST_INVALID"]),
        ("manifest-byte", &["9", "72"], &["MANIFEST_INVALID"]),           // width low byte (320 -> 328)
        ("manifest-byte", &["11", "232"], &["MANIFEST_INVALID"]),         // height low byte
        ("manifest-byte", &["12", "5"], &["MANIFEST_INVALID"]),           // cell size not whitelisted
        ("manifest-byte", &["13", "1"], &["MANIFEST_INVALID"]),           // patch count
        ("manifest-byte", &["4", "9"], &["UNSUPPORTED_VERSION"]),         // manifest version
        ("manifest-byte", &["5", "9"], &["UNSUPPORTED_VERSION"]),         // segmentation version
        ("manifest-byte", &["-2", "250"], &["MANIFEST_INVALID"]),         // map label out of range
        // --- carrier / preamble
        ("carrier-flip", &["100"], &["BOOTSTRAP_CORRUPT"]),
        ("carrier-flip", &["400"], &["BOOTSTRAP_CORRUPT"]),
        ("preamble-set", &["version", "7"], &["UNSUPPORTED_VERSION"]),
        ("preamble-set", &["version", "1"], &["UNSUPPORTED_VERSION"]),
        ("preamble-set", &["flags", "1"], &["BOOTSTRAP_CORRUPT"]),
        ("preamble-set", &["frame_len", "-5"], &["FRAME_LENGTH_INVALID"]),
        ("preamble-set", &["frame_len", "+5"], &["FRAME_LENGTH_INVALID"]),
        ("preamble-set", &["frame_len", "2147483647"], &["FRAME_LENGTH_INVALID", "FRAME_TOO_LARGE"]),
        ("preamble-set", &["manifest_len", "-3"], &["BOOTSTRAP_CORRUPT", "MANIFEST_INVALID", "FRAME_LENGTH_INVALID"]),
        ("preamble-set", &["manifest_len", "4000000000"], &["MANIFEST_TOO_LARGE", "BOOTSTRAP_CORRUPT"]),
        // --- whole-image damage
        ("blank", &[], &["BOOTSTRAP_MISSING"]),
        ("truncate", &[], &["IMAGE_DECODE_ERROR"]),
        ("garbage", &[], &["IMAGE_DECODE_ERROR"]),
        ("jpeg", &[], &["BOOTSTRAP_MISSING", "BOOTSTRAP_CORRUPT", "UNSUPPORTED_VERSION", "MANIFEST_INVALID", "MANIFEST_TOO_LARGE", "FRAME_LENGTH_INVALID", "FRAME_AUTH_FAILED", "EXTRACT_FAILED", "UNKNOWN_ALGORITHM"]),
    ];
    for (mode, raw_args, codes) in cases {
        let sent = pipeline::run_send(&st, req(&sid, "drone-1", &format!("{SECRET} {}", "t".repeat(300)), Value::Null)).unwrap_or_else(|f| panic!("send: {}", f.error));
        let id = sent["artifact"]["id"].as_str().unwrap().to_string();
        let used: Vec<&Value> = sent["manifest"]["patches"].as_array().unwrap().iter().filter(|p| p["used"] == true).collect();
        assert!(used.len() >= 2, "the tamper cases need at least two used patches");
        let u = used[0]["patch_id"].as_u64().unwrap();
        let other = used[1]["patch_id"].as_u64().unwrap();
        // a different but VALID algorithm id/parameter combination for the first used patch
        let swap = if used[0]["alg_id"] == 1 { "2" } else { "1" };
        let args: Vec<String> = raw_args.iter().map(|a| match *a { "U" => u.to_string(), "OTHER" => other.to_string(), "SWAP" => swap.to_string(),
            "COVER" => py.dir.join("artifacts").join(format!("{}.cover.png", sent["cover"]["artifact_id"].as_str().unwrap())).to_string_lossy().to_string(), x => x.to_string() }).collect();
        let argv: Vec<&str> = args.iter().map(|s| s.as_str()).collect();
        helper(mode, &png_path(&py, &id), &argv);
        let got = match pipeline::run_receive(&st, &sid, "drone-2", &id) {
            Ok(v) => panic!("[{mode} {argv:?}] delivered {:?}", v["delivered_message"]),
            Err(f) => f,
        };
        assert!(codes.contains(&got.error.code.as_str()), "[{mode} {argv:?}] got {} expected one of {codes:?}", got.error);
        assert!(!got.to_json().to_string().contains(SECRET));
        assert!(got.event_id > 0);
    }
    // the receiver is still healthy afterwards (no failure advanced the replay window)
    let ok = pipeline::run_message(&st, req(&sid, "drone-1", "after tamper", Value::Null)).unwrap_or_else(|f| panic!("{}", f.error));
    assert_eq!(ok["delivered_message"], "after tamper");
    // every tamper case that reached the Rust verifier with an intact carrier was a MAC failure
    let evs = st.lock().unwrap().db.query_stego_events(&Default::default()).unwrap();
    assert!(evs.iter().filter(|e| e["error_code"] == "FRAME_AUTH_FAILED").count() >= 3);
}

#[test]
fn payloads_beyond_the_cover_are_rejected_or_resized_never_downgraded() {
    let Some(py) = start_python("capacity") else { return };
    // frame limit raised so the rejection must come from the cover, not the size limit
    let (st, sid) = state_with(&py, 262_144);
    // (1) far beyond anything the profile may generate: structured rejection, nothing generated or written
    let big = "z".repeat(150_000);
    let e = pipeline::run_message(&st, req(&sid, "drone-1", &big, Value::Null)).err().expect("must be rejected");
    assert_eq!(e.error.code, "PATCH_CAPACITY_INSUFFICIENT", "{}", e.error);
    let d = e.error.details.clone().expect("structured details");
    assert_eq!(d["reason"], "embedding_rate_above_limit");
    assert!(d["candidates"].is_array() && d["config"]["profile"] == "raspberry_pi_5_cpu");
    assert_eq!((stego_pngs(&py), cover_pngs(&py)), (0, 0));
    // (2) above the embedding-rate limit of the default 320x240 cover, resize not allowed: rejected the same way
    let mid = "y".repeat(7_000);
    let e = pipeline::run_message(&st, req(&sid, "drone-1", &mid, Value::Null)).err().expect("must be rejected");
    assert_eq!(e.error.code, "PATCH_CAPACITY_INSUFFICIENT");
    assert_eq!(e.error.details.as_ref().unwrap()["allow_payload_driven_resize"], false);
    assert_eq!((stego_pngs(&py), cover_pngs(&py)), (0, 0));
    // (3) same payload with payload-driven resize allowed: a larger cover within the profile ceiling carries it
    let v = pipeline::run_message(&st, req(&sid, "drone-1", &mid, json!({"allow_payload_driven_resize": true}))).unwrap_or_else(|f| panic!("{}", f.error));
    assert_eq!(v["delivered_message"].as_str().unwrap().len(), 7_000);
    assert_eq!(v["generation"]["resized"], true);
    let (w, h) = (v["cover"]["width"].as_u64().unwrap(), v["cover"]["height"].as_u64().unwrap());
    assert!(w > 320 && w <= 640 && h <= 480, "{w}x{h}");
    assert_eq!(v["generation"]["requested"]["width"], 320);
    // (4) the ceiling is a ceiling: even with resize, the 150 kB payload is refused
    let e = pipeline::run_message(&st, req(&sid, "drone-1", &big, json!({"allow_payload_driven_resize": true}))).err().expect("must be rejected");
    assert_eq!(e.error.code, "PATCH_CAPACITY_INSUFFICIENT");
    let evs = st.lock().unwrap().db.query_stego_events(&Default::default()).unwrap();
    assert_eq!(evs.len(), 4);
    assert_eq!(evs.iter().filter(|e| e["success"] == false && e["generation_failure_reason"].is_string()).count(), 3);
    assert!(evs.iter().any(|e| e["success"] == true && e["cover_resized"] == true));
    assert_eq!(stego_pngs(&py), 1, "only the delivered message produced an image");
}

#[test]
fn cameras_uploads_and_client_chosen_covers_are_gone_from_the_image_service() {
    let Some(py) = start_python("removed") else { return };
    let (st, _sid) = state(&py);
    let backend = st.lock().unwrap().backend.clone();
    let cfg = st.lock().unwrap().stego_cfg.clone();
    let base = iod_core::transport::http::parse_base_url(&format!("http://127.0.0.1:{}", py.port), false).unwrap();
    for path in ["/stego/camera/probe", "/stego/cover/upload", "/stego/capture"] {
        let r = iod_core::transport::http::request(&base, "POST", path, Some(b"{}"), Duration::from_secs(5), 1 << 20).unwrap();
        assert_eq!(r.status, 404, "{path}");
    }
    let health = backend.health().unwrap();
    assert!(health.get("camera").is_none(), "no camera section in health");
    assert_eq!(health["cover_generator"]["pretrained_models"], false);
    assert_eq!(health["cover_generator"]["active_profile"], "raspberry_pi_5_cpu");
    // a cover the service did not generate (written straight into the artifact directory)
    let foreign = format!("{:032x}", rand::random::<u128>());
    helper("make-mixed-cover", &py.dir.join("artifacts").join(format!("{foreign}.cover.png")), &[]);
    let old_shapes = [
        json!({"cover": {"source": "webcam"}}), json!({"cover": {"source": "browser_webcam", "cover_id": foreign}}),
        json!({"cover": {"source": "uploaded", "cover_id": foreign}}), json!({"cover": {"source": "test_cover", "test_cover_id": foreign}}),
        json!({"cover": {"source": "procedural", "seed": "s"}}), json!({"seed": "abc"}), json!({"cover_id": foreign}), json!({"test_cover_id": foreign}),
        json!({"image_b64": "iVBORw0KGgo="}),
    ];
    for extra in old_shapes {
        let mut r = json!({"payload_bytes": 200, "limits": cfg.limits()});
        for (k, v) in extra.as_object().unwrap() {
            r[k] = v.clone();
        }
        let e = backend.plan(&r).unwrap_err();
        assert_eq!(e.code, "INVALID_REQUEST", "{extra}");
    }
    for bad in [json!({"seed": "00"}), json!({"source": "webcam"}), json!({"cover_id": foreign}), json!({"max_candidates": 5}), json!({"family": "terrain"})] {
        let e = backend.plan(&json!({"payload_bytes": 200, "cover_generation": bad, "limits": cfg.limits()})).unwrap_err();
        assert_eq!(e.code, "GENERATOR_CONFIG_INVALID", "{bad}");
    }
    // the foreign cover can be neither re-planned nor embedded into
    let e = backend.plan(&json!({"payload_bytes": 200, "replan_cover_id": foreign, "limits": cfg.limits()})).unwrap_err();
    assert!(["ARTIFACT_NOT_FOUND", "INVALID_REQUEST"].contains(&e.code.as_str()), "{}", e.code);
    let e = backend.plan(&json!({"payload_bytes": 200, "replan_cover_id": "../../etc/passwd", "limits": cfg.limits()})).unwrap_err();
    assert!(["INVALID_REQUEST", "INVALID_ARTIFACT_ID"].contains(&e.code.as_str()), "{}", e.code);
    let e = backend.encode(&json!({"frame_b64": "SU9EMg==", "cover_id": foreign, "limits": cfg.limits()})).unwrap_err();
    assert!(!["OK"].contains(&e.code.as_str()));
    assert_eq!(cover_pngs(&py), 1, "only the foreign file is present: none of the rejected requests generated or stored a cover");
    assert_eq!(stego_pngs(&py), 0);
}

#[test]
fn knowledge_base_is_served_validated_and_old_endpoints_are_gone() {
    let Some(py) = start_python("kb") else { return };
    let (st, _sid) = state(&py);
    let backend = st.lock().unwrap().backend.clone();
    let kb = backend.kb().unwrap();
    assert_eq!(kb["selector"]["version"], "kb-bm25-1");
    let entries = kb["entries"].as_array().unwrap();
    assert_eq!(entries.len(), 10);
    for (i, e) in entries.iter().enumerate() {
        assert_eq!(e["id"], i + 1);
        assert_eq!(e["name"], iod_core::transport::backend::ALGS[i]);
        assert!(e["variant"].is_string() && e["evidence"].as_array().map(|a| !a.is_empty()).unwrap_or(false));
    }
    let health = backend.health().unwrap();
    assert_eq!(health["format_version"], pipeline::TRANSPORT_FORMAT_VERSION);
    // removed endpoints of the old whole-image / generic-RAG flow
    let base = iod_core::transport::http::parse_base_url(&format!("http://127.0.0.1:{}", py.port), false).unwrap();
    for path in ["/stego/explain", "/stego/analyze", "/rag/run", "/rag/contribute"] {
        let r = iod_core::transport::http::request(&base, "POST", path, Some(b"{}"), Duration::from_secs(5), 1 << 20).unwrap();
        assert_eq!(r.status, 404, "{path}");
    }
}
